solution.python:
def count_bits(n):
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count

solution.java:
class Solution {
    public int countBits(int n) {
        int count = 0;
        while (n != 0) {
            n &= n - 1;
            count++;
        }
        return count;
    }
}

